//! The C interface C++ calls (include/rust/ee_rust.h, generated by cbindgen). Bytes given to C++ are `EeDataBytes`, freed
//! with `ee_data_bytes_free`; a text is passed as pointer and length. Everything here is a thin layer over the safe
//! modules; the panic hook (ee_panic) reports a broken invariant.

use crate::content::{compile_table, text_extension, Content};
use crate::dump::dump_table;
use crate::node::Kind;
use crate::rules::{self, Rules};
use crate::spec::{find_table, table};
use crate::text::{self, Failure};
use std::ffi::{c_char, c_void, CStr};

/// A byte buffer owned by Rust; free it with `ee_data_bytes_free`.
#[repr(C)]
pub struct EeDataBytes {
    pub ptr: *mut u8,
    pub len: usize,
}

impl EeDataBytes {
    pub const fn empty() -> Self {
        EeDataBytes { ptr: std::ptr::null_mut(), len: 0 }
    }
    fn from_vec(v: Vec<u8>) -> Self {
        if v.is_empty() {
            return Self::empty();
        }
        let b = v.into_boxed_slice();
        let len = b.len();
        EeDataBytes { ptr: Box::into_raw(b) as *mut u8, len }
    }
}

/// Frees a buffer this library returned (empty buffers are fine).
///
/// # Safety
/// `bytes` must have come from this library and not been freed already.
#[no_mangle]
pub unsafe extern "C" fn ee_data_bytes_free(bytes: EeDataBytes) {
    if !bytes.ptr.is_null() && bytes.len != 0 {
        drop(Box::from_raw(std::ptr::slice_from_raw_parts_mut(bytes.ptr, bytes.len)));
    }
}

unsafe fn slice<'a>(ptr: *const u8, len: usize) -> &'a [u8] {
    if ptr.is_null() || len == 0 {
        &[]
    } else {
        std::slice::from_raw_parts(ptr, len)
    }
}

unsafe fn cstr<'a>(name: *const c_char) -> &'a [u8] {
    CStr::from_ptr(name).to_bytes()
}

/// A sink handed to the read callback; the text goes in with `ee_data_sink_write`.
pub struct EeDataSink {
    data: Vec<u8>,
}

/// Appends to the sink a reader was given.
///
/// # Safety
/// `sink` must be the one given to the callback; `data` must be readable for `len` bytes.
#[no_mangle]
pub unsafe extern "C" fn ee_data_sink_write(sink: *mut EeDataSink, data: *const u8, len: usize) {
    (*sink).data.extend_from_slice(slice(data, len));
}

/// A text by name: true with the text written to the sink; false when there is no such text.
pub type EeDataRead = unsafe extern "C" fn(ctx: *mut c_void, name: *const c_char, sink: *mut EeDataSink) -> bool;

/// The compiler's state for one data path; every table's text is read through `read`. Not thread safe.
pub struct EeDataContent {
    content: Content,
}

/// A Content reading through a callback (from C++).
///
/// # Safety
/// `read` must stay callable, with `ctx`, until `ee_data_content_free`.
#[no_mangle]
pub unsafe extern "C" fn ee_data_content_new(read: EeDataRead, ctx: *mut c_void) -> *mut EeDataContent {
    let reader = move |name: &str| -> Option<Vec<u8>> {
        let mut cname = name.as_bytes().to_vec();
        cname.push(0);
        let mut sink = EeDataSink { data: Vec::new() };
        if read(ctx, cname.as_ptr() as *const c_char, &mut sink) {
            Some(sink.data)
        } else {
            None
        }
    };
    Box::into_raw(Box::new(EeDataContent { content: Content::new(Box::new(reader)) }))
}

/// Frees a Content.
///
/// # Safety
/// `content` must come from `ee_data_content_new`, once.
#[no_mangle]
pub unsafe extern "C" fn ee_data_content_free(content: *mut EeDataContent) {
    if !content.is_null() {
        drop(Box::from_raw(content));
    }
}

fn put_error(err: *mut EeDataBytes, f: Failure) {
    if !err.is_null() {
        // SAFETY: the out-pointer of an extern function, checked non-null
        unsafe { *err = EeDataBytes::from_vec(f.text) };
    }
}

/// Compiles a table of a Content into its db file bytes. False with the message (with its place) on the first problem;
/// on success `out` receives the bytes.
///
/// # Safety
/// `content` is a live Content, `table_name` NUL-terminated, `out`/`err` writable (or `err` null).
#[no_mangle]
pub unsafe extern "C" fn ee_data_compile(
    content: *mut EeDataContent,
    table_name: *const c_char,
    out: *mut EeDataBytes,
    err: *mut EeDataBytes,
) -> bool {
    let name = cstr(table_name);
    let Some(t) = find_table(name) else {
        let mut text = name.to_vec();
        text.extend_from_slice(b": not a db table with a text form");
        put_error(err, Failure::new(text));
        return false;
    };
    match (*content).content.compile(t) {
        Ok(bytes) => {
            *out = EeDataBytes::from_vec(bytes);
            true
        }
        Err(f) => {
            put_error(err, f);
            false
        }
    }
}

/// One table on its own: `text` compiled without any other table's text (a reference by id is an error then).
///
/// # Safety
/// `table_name` NUL-terminated, `text` readable for `len` bytes, `out`/`err` writable (or `err` null).
#[no_mangle]
pub unsafe extern "C" fn ee_data_compile_text(
    table_name: *const c_char,
    text: *const u8,
    len: usize,
    out: *mut EeDataBytes,
    err: *mut EeDataBytes,
) -> bool {
    match compile_table(cstr(table_name), slice(text, len)) {
        Ok(bytes) => {
            *out = EeDataBytes::from_vec(bytes);
            true
        }
        Err(f) => {
            put_error(err, f);
            false
        }
    }
}

/// The text file extension of a db table or rules document (".csv"/".yaml"), null when it has no text form.
/// `name` is the file stem, case-insensitive. The result is static.
///
/// # Safety
/// `name` must be NUL-terminated.
#[no_mangle]
pub unsafe extern "C" fn ee_data_text_extension(name: *const c_char) -> *const c_char {
    match text_extension(cstr(name)) {
        Some(".csv") => c".csv".as_ptr(),
        Some(_) => c".yaml".as_ptr(),
        None => std::ptr::null(),
    }
}

/// One entry of `ee_data_ids`.
pub type EeDataIdVisit = unsafe extern "C" fn(ctx: *mut c_void, key: i32, id: *const u8, len: usize);

/// The ids of a table's listed rows by key (false with a message when the table has no text or does not parse).
///
/// # Safety
/// `content` live, `table_name` NUL-terminated, `visit` callable with `ctx`, `err` writable or null.
#[no_mangle]
pub unsafe extern "C" fn ee_data_ids(
    content: *mut EeDataContent,
    table_name: *const c_char,
    visit: EeDataIdVisit,
    ctx: *mut c_void,
    err: *mut EeDataBytes,
) -> bool {
    let name = cstr(table_name);
    let Some(t) = find_table(name) else {
        let mut text = name.to_vec();
        text.extend_from_slice(b": not a db table with a text form");
        put_error(err, Failure::new(text));
        return false;
    };
    match (*content).content.ids(t.name) {
        Ok(ids) => {
            for (k, id) in ids.ids.iter() {
                visit(ctx, *k as i32, id.as_ptr(), id.len());
            }
            true
        }
        Err(f) => {
            put_error(err, f);
            false
        }
    }
}

/// Appends the content dump of a table's db file bytes to `out` (`"name":[...]`).
///
/// # Safety
/// `table_name` NUL-terminated, `data` readable for `len` bytes, `out`/`err` writable or `err` null.
#[no_mangle]
pub unsafe extern "C" fn ee_data_dump_table(
    table_name: *const c_char,
    data: *const u8,
    len: usize,
    out: *mut EeDataBytes,
    err: *mut EeDataBytes,
) -> bool {
    let mut text = Vec::new();
    let name = String::from_utf8_lossy(cstr(table_name)).into_owned();
    match dump_table(&name, slice(data, len), &mut text) {
        Ok(()) => {
            *out = EeDataBytes::from_vec(text);
            true
        }
        Err(f) => {
            put_error(err, f);
            false
        }
    }
}

/// The game's text (UTF-8) -> a double-quoted YAML scalar.
///
/// # Safety
/// `bytes` readable for `len` bytes, `out` writable.
#[no_mangle]
pub unsafe extern "C" fn ee_data_quote_text(bytes: *const u8, len: usize, out: *mut EeDataBytes) {
    *out = EeDataBytes::from_vec(text::quote_text(slice(bytes, len)));
}

/// One keyed upgrade of a `.civ` text: its key and line.
pub type EeDataCivVisit = unsafe extern "C" fn(ctx: *mut c_void, key: *const u8, key_len: usize, line: i32);

/// Reads a keyed `.civ` text: its name as UTF-8 bytes (`name`), its upgrades through `visit` (the list's items in
/// order; only when the document is a mapping). The error (with `where_`) is in `err`: false on a parse problem or
/// when the document is not a mapping ("<where>: not a civilization").
///
/// # Safety
/// `text` readable for `len` bytes, `where_` NUL-terminated, `name`/`err` writable, `visit` callable with `ctx`.
#[no_mangle]
pub unsafe extern "C" fn ee_data_civ_read(
    text_ptr: *const u8,
    len: usize,
    where_: *const c_char,
    name: *mut EeDataBytes,
    visit: EeDataCivVisit,
    ctx: *mut c_void,
    err: *mut EeDataBytes,
) -> bool {
    let w = cstr(where_);
    let doc = match text::parse_yaml(slice(text_ptr, len)) {
        Ok(d) if d.kind == Kind::Map => d,
        Ok(_) => {
            let mut e = w.to_vec();
            e.extend_from_slice(b": not a civilization");
            put_error(err, Failure::new(e));
            return false;
        }
        Err(f) => {
            put_error(err, f);
            return false;
        }
    };
    match text::node_text(doc.find(b"name"), w, "name") {
        Ok(n) => *name = EeDataBytes::from_vec(n),
        Err(f) => {
            put_error(err, f);
            return false;
        }
    }
    if let Some(list) = doc.find(b"upgrades").filter(|l| l.kind == Kind::List) {
        for item in &list.items {
            let key: &[u8] = if item.kind == Kind::Scalar { &item.text } else { &[] };
            visit(ctx, key.as_ptr(), key.len(), item.line as i32);
        }
    }
    true
}

// ------------------------------------------------------------------------------------------------ rules

/// The rules (ee/EERules.h, its `mRust`). Every field starts at its default.
pub struct EeDataRules {
    rules: Rules,
}

#[no_mangle]
pub extern "C" fn ee_data_rules_new() -> *mut EeDataRules {
    Box::into_raw(Box::new(EeDataRules { rules: Rules::default() }))
}

/// # Safety
/// `rules` must come from `ee_data_rules_new`, once.
#[no_mangle]
pub unsafe extern "C" fn ee_data_rules_free(rules: *mut EeDataRules) {
    if !rules.is_null() {
        drop(Box::from_raw(rules));
    }
}

/// Reads the rules documents through the Content; false with a message on the first problem.
///
/// # Safety
/// `rules` and `content` live, `err` writable or null.
#[no_mangle]
pub unsafe extern "C" fn ee_data_rules_load(
    rules: *mut EeDataRules,
    content: *mut EeDataContent,
    err: *mut EeDataBytes,
) -> bool {
    match (*rules).rules.load(&mut (*content).content) {
        Ok(()) => true,
        Err(f) => {
            put_error(err, f);
            false
        }
    }
}

/// The snapshot the C++ `EERules` decodes (EERulesGenDecode.inl).
///
/// # Safety
/// `rules` live, `out` writable.
#[no_mangle]
pub unsafe extern "C" fn ee_data_rules_encode(rules: *const EeDataRules, out: *mut EeDataBytes) {
    *out = EeDataBytes::from_vec((*rules).rules.encode());
}

/// The content dump of the rules (`"rules.<doc>":{...}` lines).
///
/// # Safety
/// `rules` live, `out` writable.
#[no_mangle]
pub unsafe extern "C" fn ee_data_rules_dump(rules: *const EeDataRules, out: *mut EeDataBytes) {
    *out = EeDataBytes::from_vec((*rules).rules.dump());
}

/// A song's per-epoch flags from dbmusic (no-op when epochs.yaml named the songs).
///
/// # Safety
/// `rules` live, `flags` readable for `count` entries.
#[no_mangle]
pub unsafe extern "C" fn ee_data_rules_set_music_from_flags(
    rules: *mut EeDataRules,
    song: i32,
    flags: *const bool,
    count: usize,
) {
    let f: &[bool] = if flags.is_null() { &[] } else { std::slice::from_raw_parts(flags, count) };
    (*rules).rules.set_music_from_flags(song, f);
}

/// The binary load's songs: every row of a dbmusic.dat file's per-epoch flags (the gate's and tools' path).
///
/// # Safety
/// `rules` live, `data` readable for `len` bytes.
#[no_mangle]
pub unsafe extern "C" fn ee_data_rules_music_from_dbmusic(
    rules: *mut EeDataRules,
    data: *const u8,
    len: usize,
) -> bool {
    let t = table("dbmusic");
    let data = slice(data, len);
    let Some(f) = t.find_field("mInEpoch") else { return false };
    if data.len() < 4 {
        return false;
    }
    let n = u32::from_le_bytes([data[0], data[1], data[2], data[3]]) as usize;
    let size = t.record.size as usize;
    if data.len() < 4 + n * size {
        return false;
    }
    for r in 0..n {
        let flags: Vec<bool> =
            (0..(f.count as usize).min(64)).map(|k| data[4 + r * size + f.offset as usize + k] != 0).collect();
        (*rules).rules.set_music_from_flags(r as i32, &flags);
    }
    true
}

/// TEST ONLY (EE-SIM --set): adds a rules override; false with the reason in `err`.
///
/// # Safety
/// `spec` readable for `len` bytes, `err` writable or null.
#[no_mangle]
pub unsafe extern "C" fn ee_data_rules_add_override(spec: *const u8, len: usize, err: *mut EeDataBytes) -> bool {
    match rules::add_override(slice(spec, len)) {
        Ok(()) => true,
        Err(e) => {
            put_error(err, Failure::new(e));
            false
        }
    }
}

/// TEST ONLY: the overrides that changed nothing, one reason per line in `out`.
///
/// # Safety
/// `out` writable.
#[no_mangle]
pub unsafe extern "C" fn ee_data_rules_override_problems(out: *mut EeDataBytes) {
    let mut text = Vec::new();
    for p in rules::override_problems() {
        text.extend_from_slice(&p);
        text.push(b'\n');
    }
    *out = EeDataBytes::from_vec(text);
}

/// The names of the unit categories, for C++: `kEERuleCategoryNames[]` is generated (EERulesGen.h); this is its count
/// source of truth for a consistency check in tests.
#[no_mangle]
pub extern "C" fn ee_data_rule_category_count() -> usize {
    crate::generated::rules_gen::UNIT_CATEGORY_NAMES.len()
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::collections::HashMap;
    use std::ffi::CString;

    unsafe extern "C" fn read_cb(ctx: *mut c_void, name: *const c_char, sink: *mut EeDataSink) -> bool {
        let map = &*(ctx as *const HashMap<String, Vec<u8>>);
        match map.get(CStr::from_ptr(name).to_str().unwrap()) {
            Some(v) => {
                ee_data_sink_write(sink, v.as_ptr(), v.len());
                true
            }
            None => false,
        }
    }

    fn take(b: &mut EeDataBytes) -> Vec<u8> {
        let v = unsafe { slice(b.ptr, b.len).to_vec() };
        unsafe { ee_data_bytes_free(std::mem::replace(b, EeDataBytes::empty())) };
        v
    }

    const WORLD: &str =
        "#eedata dbworld\n#format 3\nrow,id,mFloatValue,mFloatValue2,mLongValue,mLongValue2\n0,alpha,1.5,0,7,2\n";

    #[test]
    fn compile_through_the_c_api() {
        let map: HashMap<String, Vec<u8>> = [("dbworld".to_string(), WORLD.as_bytes().to_vec())].into_iter().collect();
        unsafe {
            let c = ee_data_content_new(read_cb, &map as *const _ as *mut c_void);
            let name = CString::new("dbworld").unwrap();
            let mut out = EeDataBytes::empty();
            let mut err = EeDataBytes::empty();
            assert!(ee_data_compile(c, name.as_ptr(), &mut out, &mut err));
            let bytes = take(&mut out);
            assert_eq!(bytes.len(), 4 + table("dbworld").record.size as usize);

            let missing = CString::new("nosuch").unwrap();
            assert!(!ee_data_compile(c, missing.as_ptr(), &mut out, &mut err));
            assert_eq!(take(&mut err), b"nosuch: not a db table with a text form".to_vec());

            let mut seen: Vec<(i32, Vec<u8>)> = Vec::new();
            unsafe extern "C" fn visit(ctx: *mut c_void, key: i32, id: *const u8, len: usize) {
                (*(ctx as *mut Vec<(i32, Vec<u8>)>)).push((key, slice(id, len).to_vec()));
            }
            assert!(ee_data_ids(c, name.as_ptr(), visit, &mut seen as *mut _ as *mut c_void, &mut err));
            assert_eq!(seen, vec![(0, b"alpha".to_vec())]);
            ee_data_content_free(c);
        }
    }

    #[test]
    fn compile_text_and_errors() {
        unsafe {
            let name = CString::new("dbworld").unwrap();
            let mut out = EeDataBytes::empty();
            let mut err = EeDataBytes::empty();
            let bad = b"#format 2\nrow,id\n";
            assert!(!ee_data_compile_text(name.as_ptr(), bad.as_ptr(), bad.len(), &mut out, &mut err));
            assert!(take(&mut err).ends_with(b"this loader reads format 3"));
            assert!(ee_data_compile_text(name.as_ptr(), WORLD.as_ptr(), WORLD.len(), &mut out, &mut err));
            assert!(!take(&mut out).is_empty());
        }
    }

    #[test]
    fn dump_through_the_c_api() {
        unsafe {
            let name = CString::new("dbworld").unwrap();
            let mut rec = 1u32.to_le_bytes().to_vec();
            rec.extend(vec![0u8; table("dbworld").record.size as usize]);
            let mut out = EeDataBytes::empty();
            let mut err = EeDataBytes::empty();
            assert!(ee_data_dump_table(name.as_ptr(), rec.as_ptr(), rec.len(), &mut out, &mut err));
            assert!(take(&mut out).starts_with(b"\"dbworld\":["));
            let t = CString::new("nosuch").unwrap();
            assert!(!ee_data_dump_table(t.as_ptr(), rec.as_ptr(), rec.len(), &mut out, &mut err));
            take(&mut err);
        }
    }

    #[test]
    fn extensions_are_static_c_strings() {
        unsafe {
            let n = CString::new("dbWorld").unwrap();
            assert_eq!(CStr::from_ptr(ee_data_text_extension(n.as_ptr())).to_bytes(), b".csv");
            let n = CString::new("combat").unwrap();
            assert_eq!(CStr::from_ptr(ee_data_text_extension(n.as_ptr())).to_bytes(), b".yaml");
            let n = CString::new("nope").unwrap();
            assert!(ee_data_text_extension(n.as_ptr()).is_null());
        }
    }

    #[test]
    fn empty_buffers_are_safe_to_free() {
        unsafe {
            ee_data_bytes_free(EeDataBytes::empty());
            ee_data_content_free(std::ptr::null_mut());
            ee_data_rules_free(std::ptr::null_mut());
            let mut out = EeDataBytes::empty();
            ee_data_quote_text(b"".as_ptr(), 0, &mut out);
            assert_eq!(take(&mut out), b"\"\"".to_vec());
        }
    }

    #[test]
    fn civ_read_through_the_c_api() {
        unsafe extern "C" fn visit(ctx: *mut c_void, key: *const u8, len: usize, line: i32) {
            (*(ctx as *mut Vec<(Vec<u8>, i32)>)).push((slice(key, len).to_vec(), line));
        }
        unsafe {
            let doc = "eedata: civ\nformat: 3\nname: \"caf\u{e9}\"\nupgrades: [a.b, c.d]\n";
            let w = CString::new("my.civ").unwrap();
            let mut name = EeDataBytes::empty();
            let mut err = EeDataBytes::empty();
            let mut seen: Vec<(Vec<u8>, i32)> = Vec::new();
            assert!(ee_data_civ_read(
                doc.as_ptr(),
                doc.len(),
                w.as_ptr(),
                &mut name,
                visit,
                &mut seen as *mut _ as *mut c_void,
                &mut err
            ));
            assert_eq!(take(&mut name), "caf\u{e9}".as_bytes());
            assert_eq!(seen, vec![(b"a.b".to_vec(), 4), (b"c.d".to_vec(), 4)]);
            let bad = "- 1\n";
            assert!(!ee_data_civ_read(
                bad.as_ptr(),
                bad.len(),
                w.as_ptr(),
                &mut name,
                visit,
                &mut seen as *mut _ as *mut c_void,
                &mut err
            ));
            assert_eq!(take(&mut err), b"my.civ: not a civilization".to_vec());
            let bad = "name: [1]\n";
            assert!(!ee_data_civ_read(
                bad.as_ptr(),
                bad.len(),
                w.as_ptr(),
                &mut name,
                visit,
                &mut seen as *mut _ as *mut c_void,
                &mut err
            ));
            assert_eq!(take(&mut err), b"my.civ: name: a list where a string belongs".to_vec());
        }
    }

    #[test]
    fn rules_through_the_c_api() {
        let map: HashMap<String, Vec<u8>> =
            [("combat".to_string(), b"damage:\n  minimum: 2\n".to_vec())].into_iter().collect();
        unsafe {
            let c = ee_data_content_new(read_cb, &map as *const _ as *mut c_void);
            let r = ee_data_rules_new();
            let mut err = EeDataBytes::empty();
            assert!(ee_data_rules_load(r, c, &mut err));
            let mut out = EeDataBytes::empty();
            ee_data_rules_dump(r, &mut out);
            assert!(take(&mut out).starts_with(b"\"rules.combat\":{\"minimum_damage\":2,"));
            ee_data_rules_encode(r, &mut out);
            assert!(!take(&mut out).is_empty());
            let flags = [true; 14];
            ee_data_rules_set_music_from_flags(r, 3, flags.as_ptr(), flags.len());
            ee_data_rules_free(r);
            ee_data_content_free(c);
        }
    }

    #[test]
    fn dbmusic_flags_from_bytes() {
        let t = table("dbmusic");
        let mut d = 1u32.to_le_bytes().to_vec();
        d.extend(vec![1u8; t.record.size as usize]);
        unsafe {
            let r = ee_data_rules_new();
            assert!(ee_data_rules_music_from_dbmusic(r, d.as_ptr(), d.len()));
            let epochs = &(*r).rules.epochs;
            assert_eq!(epochs[0].music, vec![0]);
            assert!(!ee_data_rules_music_from_dbmusic(r, d.as_ptr(), 3));
            ee_data_rules_free(r);
        }
    }

    #[test]
    fn overrides_through_the_c_api() {
        rules::clear_overrides();
        unsafe {
            let mut err = EeDataBytes::empty();
            let spec = b"combat";
            assert!(!ee_data_rules_add_override(spec.as_ptr(), spec.len(), &mut err));
            assert_eq!(take(&mut err), b"'combat': expected doc.key...=value".to_vec());
            let mut out = EeDataBytes::empty();
            let spec = b"combat.x=1";
            assert!(ee_data_rules_add_override(spec.as_ptr(), spec.len(), &mut err));
            ee_data_rules_override_problems(&mut out);
            assert_eq!(take(&mut out), b"combat: its document was not read\n".to_vec());
        }
        rules::clear_overrides();
        assert_eq!(ee_data_rule_category_count(), 35);
    }
}
